insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"MARGIN_GTE_3","title":"¿El ganador tendrá ventaja de 3 o más?","description":"Se corrige con el marcador final.","category":"diferencia","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":3},"priority":0,"cooldown":2,"tags":["diferencia"]},{"code":"MARGIN_GTE_4","title":"¿Habrá diferencia de 4 o más carreras?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":4},"priority":0,"cooldown":2,"tags":["abierto"]},{"code":"MARGIN_GTE_5","title":"¿La ventaja final será de 5 o más?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":5},"priority":0,"cooldown":2,"tags":["abierto"]},{"code":"MARGIN_GTE_6","title":"¿Alguien se irá con 6 o más de ventaja?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":6},"priority":0,"cooldown":2,"tags":["abierto"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;